	}))
	t.Cleanup(srv.Close)
	imgs, out, err := catalogOutcome(t, CatalogSearcher{}, Target{APIURL: srv.URL, RepoPrefix: "docker-hosted"}, "api")
	if err != nil || out.Verdict != VerdictOK || len(imgs) != 1 {
		t.Fatalf("imgs = %+v out = %+v err = %v", imgs, out, err)
	}
