	}
	if len(imgs) != 100 {
		t.Errorf("rows = %d, want 100", len(imgs))
	}
	if out != (Outcome{Verdict: VerdictOK, Partial: true}) {
		t.Errorf("outcome = %+v, want ok + Partial", out)
	}
}

